}

public static METCrossDockTransferOrderProcessorBase construct(Common _sourceTable)
{
    METCrossDockTransferOrderProcessorBase processor;

    if(tableNum(SalesTable) == _sourceTable.TableId)
    {
        processor = new METCrossDockTransferOrderProcessor_SalesOrder();
    }
    else if(tableNum(SalesLine) == _sourceTable.TableId)
    {
        processor = new METCrossDockTransferOrderProcessor_SalesOrder();
    }
    else if(tableNum(InventTransferTable) == _sourceTable.TableId)
    {
        processor = new METCrossDockTransferOrderProcessor_TransferOrder();
    }

    processor.init(_sourceTable);

    return processor;
}

