/// <summary>
/// 
/// </summary>
/// <param name = "_transLineExt"></param>
/// <param name = "_transLine"></param>
/// <returns></returns>
protected METInventTransferLine createOrUpdateTransferLineExt(METInventTransferLine _transLineExt, InventTransferLine _transLine)
{
    _transLineExt.clear();
    _transLineExt.initValue();
    _transLineExt.InventTransferLine = _transLine.RecId;

    _transLineExt.AllowSubstitution = this.shouldAllowSubstitution();

    //If the Salesline order extraction status is already extracted means the transfer order line is being created as an effect of a substitution process.
    //In that case we need to set the transfer line extraction status to Ready to Extract, so the line is picked in the second pick list attempt.
    _transLineExt.OrderExtractStatus = this.getExtractionStatus();
    this.setSourceLineReference(_transLineExt);

    return _transLineExt;

}

